// Baut den Note-Body aus Workshop + Trainer + Submission-Daten.
// Format gemäß setup/hubspot-note-template.md.

const body     = $('Webhook').item.json.body;
const workshop = $('Query Workshop').first().json.results[0];
const trainers = $('Query Trainer').first().json.results;

// Trainer-Lookup über den Multi-Link
function firstLinkedId(link) {
  if (!Array.isArray(link) || link.length === 0) return null;
  const first = link[0];
  if (typeof first === 'string') return first;
  if (first && typeof first === 'object' && first.row_id) return first.row_id;
  return null;
}
const trainerId = firstLinkedId(workshop.Trainer);
const trainer   = trainerId ? trainers.find(t => t._id === trainerId) : null;
const trainerName = trainer ? (trainer.Name || '') : '';

// Datum DD.MM.YYYY (SeaTable liefert ISO 'YYYY-MM-DD')
function formatDatum(iso) {
  if (!iso) return '';
  const m = String(iso).match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (!m) return iso;
  return `${m[3]}.${m[2]}.${m[1]}`;
}
const datum = formatDatum(workshop.Datum);

const noteBody = [
  `${workshop.Name || '—'} – ${datum}`,
  trainerName ? `Trainer: ${trainerName}` : '',
  '',
  'Vorhaben (6 Wochen):',
  body.vorhaben_6w || '—',
  '',
  'Nächster Schritt (72h):',
  body.naechster_schritt_72h || '—',
  '',
  `LIFO-Interesse: ${body.lifo_interest || '—'}`,
  `LIFO-Stärke: ${body.lifo_staerke || '—'}`
].filter(line => line !== null).join('\n');

return [{ json: {
  note_body: noteBody,
  hs_timestamp: new Date().toISOString(),
  trainer_name: trainerName,
  trainer_email: trainer ? (trainer.Email || '') : '',
  trainer_photo: trainer ? (trainer.FotoUrl || '') : '',
  trainer_signature: trainer ? (trainer.SignatureHtml || '') : '',
  workshop_name: workshop.Name || '',
  workshop_datum: workshop.Datum || '',
  workshop_lifo_verwendet: !!workshop.LifoVerwendet
} }];

