// Berechnet die ScheduledEmails für diese Submission.
// Spec: SendAt = now() + offset (NICHT relativ zu Workshop.Datum, weil
// verschiedene Teilnehmer:innen denselben Workshop zu unterschiedlichen
// Zeiten submitten — der 24h-Anker bezieht sich auf 'morgen früh' aus
// Sicht des Teilnehmers).
//
// Subject ist die SeaTable-Key-Spalte UND wird vom email-sender als
// Mail-Betreff verwendet — daher direkt user-facing formuliert.

const body    = $('Webhook').item.json.body;
const ctx     = $('Build Note Body + Workshop-Context').item.json;
const createR = $('Create Submission Row').first().json;
const submissionId = (createR && createR.row_ids && createR.row_ids[0])
                  || (createR && createR.first_row && createR.first_row._id)
                  || (createR && createR._id);

function sendAt(hoursFromNow) {
  const d = new Date(Date.now() + hoursFromNow * 3600 * 1000);
  // SeaTable date+time format: 'YYYY-MM-DD HH:mm:ss' (ohne Timezone-Suffix)
  const pad = n => String(n).padStart(2, '0');
  return `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())} `
       + `${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}:${pad(d.getUTCSeconds())}`;
}

const rows = [
  {
    Subject:    `Deine Vorhaben aus dem Workshop ${ctx.workshop_name}`.slice(0, 250),
    Submission: [submissionId],
    Type:       'thanks_24h',
    SendAt:     sendAt(24),
    Status:     'pending'
  },
  {
    Subject:    'Hast du deinen ersten Schritt gemacht?',
    Submission: [submissionId],
    Type:       'followup_78h',
    SendAt:     sendAt(78),
    Status:     'pending'
  },
  {
    Subject:    '6 Wochen sind um — wo stehst du?',
    Submission: [submissionId],
    Type:       'final_6w',
    SendAt:     sendAt(24 * 42),
    Status:     'pending'
  }
];

// LIFO-Followup nur wenn Workshop LIFO eingesetzt UND Teilnehmer Interesse hat.
// Webform liefert lifo_interest 'ja'|'nein' (nie 'vielleicht'), aber für
// Forward-Compat wird auch 'vielleicht' getriggert.
if (ctx.workshop_lifo_verwendet && ['ja', 'vielleicht'].includes(body.lifo_interest)) {
  rows.push({
    Subject:    'Magst du mit deinem LIFO-Profil weiterarbeiten?',
    Submission: [submissionId],
    Type:       'lifo_followup',
    SendAt:     sendAt(24 * 28),
    Status:     'pending'
  });
}

return [{ json: { table_name: 'ScheduledEmails', rows } }];

